// Models embedded as base64 so the page needs no .glb hosting.
const DATA = {
  apollo: "",
  rover: "",
  suit: "",
};
function toBuffer(b64) {
  const bin = atob(b64);
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return u8.buffer;
}
/** Same call shape as GLTFLoader.load, but parses an embedded model in memory. */
export function loadGlb(loader, key, onLoad, _onProgress, onError) {
  try {
    loader.parse(toBuffer(DATA[key]), "", onLoad, onError);
  } catch (e) {
    if (onError) onError(e);
  }
}
